// --- Start of game_logic/main.c ---
#include <stdint.h>
#include <stdlib.h>
//#include"weapon.h"
// Stripped local include: #include"map.h"
// Stripped local include: #include"player.h"
// Stripped local include: #include"../hardware/ps2.h"
//#include"../hardware/timer.h"
// Stripped local include: #include"../hardware/vga.h"
// Stripped local include: #include"../sources/knight_anim.h"


// 1. 定义洋红色的 RGB565 值
#define COLOR_MAGENTA_565  0xF81F  

// 2. CPUlator DE1-SoC 默认的 VGA 显存基地址 (请根据你实际 BSP 手册确认，通常是这个)


// 假设你的屏幕分辨率是 320x240

short int Buffer0[240][512]; // 240 rows, 512 (320 + padding) columns
short int Buffer1[240][512];
int current_buffer = 0;         // can be 0 or 1 corresponding to current buffer

int prev_knight_x[2] = {100, 100};
int prev_knight_y[2] = {100, 100};

int main(void){

    volatile int * pixel_ctrl_ptr = (int *)0xFF203020;

    *(pixel_ctrl_ptr + 1) = (int) &Buffer0;

    vga_wait_for_vsync();
    pixel_buffer_start = *pixel_ctrl_ptr;
    clear_screen();
    Draw_Transparent_Image(0, 0, background_ptr, 320, 240);

    *(pixel_ctrl_ptr + 1) = (int) &Buffer1;
    pixel_buffer_start = *(pixel_ctrl_ptr + 1);
    clear_screen();                            
    Draw_Transparent_Image(0, 0, background_ptr, 320, 240);     //write the opening image to the buffers

    Player knight_entity;
    
    Player_Init(&knight_entity, 144, 104);
    PS2_Init();             // init the keys WASD to 0;
    Player* knight = & knight_entity;

    unsigned int random_seed = 0; // 种子计数器

    // 这里其实可以画一行字："Press WASD to Start"
    // 但就算不画，玩家进来肯定会习惯性按一下键盘

    while (1) {
        random_seed++; // 以 CPU 全速疯狂自增 (每秒几百万次)
        
        PS2_Update();
        // 只要玩家按下了 W, A, S, D 中的任意一个键
        if (key_W || key_A || key_S || key_D) {
            break; // 瞬间打破循环！
        }
    }
    vga_wait_for_vsync();
    pixel_buffer_start = *pixel_ctrl_ptr;
    clear_screen();

    *(pixel_ctrl_ptr + 1) = (int) &Buffer1;
    pixel_buffer_start = *(pixel_ctrl_ptr + 1);
    clear_screen();                             // clean up two buffers, make sure all black

    // 注入灵魂：用玩家反应时间这一瞬的数字，初始化随机数发生器！
    srand(random_seed); 

    init_world_map();
    current_room_x = 6;
    current_room_y = 6;
    init_walls();
    draw_walls();

	while(1){
        PS2_Update();

        int dx = 0, dy = 0;
        if (key_W) dy -= 1;
        if (key_S) dy += 1;
        if (key_A) dx -= 1;
        if (key_D) dx += 1;

        Player_Update(knight, dx, dy);
        if (handle_room_transition(knight)) {
            // 如果发生了传送，必须重置 prev 坐标
            // 否则 vga_draw_rect 会去屏幕另一头擦除一个“幽灵残影”
            prev_knight_x[0] = prev_knight_x[1] = knight->x;
            prev_knight_y[0] = prev_knight_y[1] = knight->y;
        }
        vga_draw_rect(prev_knight_x[current_buffer], prev_knight_y[current_buffer], knight->width, knight->height, Black);

        draw_walls();
        draw_world_map();

        Player_Draw(knight);
        prev_knight_x[current_buffer] = knight->x;
        prev_knight_y[current_buffer] = knight->y;

        vga_wait_for_vsync(); // swap front and back buffers on VGA vertical sync
        pixel_buffer_start = *(pixel_ctrl_ptr + 1); // new back buffer
        current_buffer = 1 - current_buffer;
	}
    return 0; 
}
// --- End of game_logic/main.c ---

// --- Start of game_logic/map.c ---
// Stripped local include: #include "map.h"
#include <stdlib.h>
// Stripped local include: #include "../hardware/vga.h"
// Stripped local include: #include "../sources/knight_anim.h"

int current_inner_texture = 0;
int max_rooms = 0;
int walls[16][12] = {0};
extern int walls[GRID_W][GRID_H];

Room world_map[world_map_max][world_map_max];     //13 * 13 room space
Room seed_map[world_map_max][world_map_max];
int init_x = 6;
int init_y = 6;
int current_room_x = 6;
int current_room_y = 6;

void init_world_map(){
    for (int i = 0; i < world_map_max; i ++){
        for (int j = 0; j < world_map_max; j ++){
            world_map[i][j].exists = 0;
        }
    }

    current_room_x = 6;
    current_room_y = 6;

    int count = 1;
    max_rooms = rand()%2 +5;

    // 确保起始房间默认是清空的，否则一出生就被怪围住
    world_map[current_room_x][current_room_y].is_cleared = 1; 
    world_map[current_room_x][current_room_y].exists = 1;
    int rx = 6, ry = 6;
    while(count < max_rooms) {
        int dir = rand() % 4;
        if(dir == 0) ry--;      // 上
        else if(dir == 1) ry++; // 下
        else if(dir == 2) rx--; // 左
        else rx++; 

        if(world_map[rx][ry].exists == 0) {
            world_map[rx][ry].exists = 1;
            world_map[rx][ry].is_cleared = 1;   // so far, set all the rooms cleared before battle system developed
            count++;
        }
        else{continue;}
    }
}

void apply_doors_to_walls() {       // the position of walls
    // 只有房间清空了才执行开门逻辑
    if (world_map[current_room_x][current_room_y].is_cleared == 0) {
        return; 
    }

    // 检查上方：如果北边有房间，挖开顶部中间
    if (world_map[current_room_x][current_room_y - 1].exists) {
        walls[7][0] = 2; walls[8][0] = 2;
    }
    // 检查下方：如果南边有房间，挖开底部中间
    if (world_map[current_room_x][current_room_y + 1].exists) {
        walls[7][11] = 2; walls[8][11] = 2;
    }
    // 检查左方：如果西边有房间，挖开左侧中间
    if (world_map[current_room_x - 1][current_room_y].exists) {
        walls[0][5] = 2; walls[0][6] = 2;
    }
    // 检查右方：如果东边有房间，挖开右侧中间
    if (world_map[current_room_x + 1][current_room_y].exists) {
        walls[15][5] = 2; walls[15][6] = 2;
    }
}

int handle_room_transition(Player *p) { // return 1 if jumped
    int teleported = 0;

    // 检测四个边缘
    if (p->y < -5) {
        current_room_y--; p->y = 204; teleported = 1;
    } else if (p->y > 205) {
        current_room_y++; p->y = 10;  teleported = 1;
    } else if (p->x < -5) {
        current_room_x--; p->x = 285; teleported = 1;
    } else if (p->x > 286) {
        current_room_x++; p->x = 10;  teleported = 1;
    }

    if (teleported) {
        // 1. 重新生成地形（掩体随机变化）
        init_walls();
        
        // 2. 根据逻辑打开新房间的大门
        // 如果新房间之前打过了，门是开的；如果没打过，门是关的
        apply_doors_to_walls();

        // 3. 彻底重置双缓冲，防止旧房间残影（这是最简洁的处理方式）
        clear_screen(); 
        vga_wait_for_vsync(); // 等待同步
        clear_screen(); 
        
        // 4. (预留) 在这里可以根据 is_cleared 决定是否刷怪
    }

    return teleported;
}

void draw_world_map() {
    int min_i = 4, min_j = 4; // 初始设为最大值

    // 2. 第二遍扫描：绘图
    int map_offset_x = 10; // 小地图距离屏幕左边的边距
    int map_offset_y = 10; // 小地图距离屏幕顶部的边距
    int room_size = 6;     // 每个小房间方块的大小
    int spacing = 8;      // 房间中心之间的间距 (留2像素空隙)

    //vga_draw_rect(0, 0, room_size * 7, room_size * 8, Grey);

    for (int i = 0; i < 13; i++) {
        for (int j = 0; j < 13; j++) {
            if (world_map[i][j].exists) {
                // 计算在屏幕上的绝对像素坐标
                // (i - min_i) 确保最左边的房间从 0 开始算
                int draw_x = map_offset_x + (i - min_i) * spacing;
                int draw_y = map_offset_y + (j - min_j) * spacing;

                // 3. 区分颜色显示
                short int color;
                if (i == current_room_x && j == current_room_y) {
                    color = Green; // 玩家当前所在房间用绿色
                } else if (world_map[i][j].is_cleared) {
                    color = Blue;  // 已清空的房间用蓝色
                } else {
                    color = Red;   // 有怪的房间用红色
                }

                // 绘制小方块 (可以使用你之前的画矩形函数)
                vga_draw_rect(draw_x, draw_y, room_size, room_size, color);
            }
        }
    }
}

void init_walls() {
    // 1. 初始化清空数组 (确保每次重新生成都是一张白纸)
    for(int x = 0; x < GRID_W; x++) {
        for(int y = 0; y < GRID_H; y++) {
            walls[x][y] = 0;
        }
    }

    // 2. 生成外围的绝对边界
    for(int i = 0; i < GRID_W; i++ ){
        walls[i][0] = 1;           // 顶边
        walls[i][GRID_H - 1] = 1;  // 底边
    }
    for(int i = 0; i < GRID_H; i++ ){
        walls[0][i] = 1;           // 左边
        walls[GRID_W - 1][i] = 1;  // 右边
    }


    int num_clusters = rand() % 3 + 2; // 随机丢 2 到 4 个掩体堆
    current_inner_texture = rand()%5;

    for(int c = 0; c < num_clusters; c++) {
        int shape = rand() % 5;      // 随机抽取 5 种掩体形状之一
        int cx = rand() % 3 + 2;     // 掩体的基准 X 坐标 (2, 3, 4)
        int cy = rand() % 4 + 3;     // 掩体的基准 Y 坐标 (2~7)

        if (shape == 0) { 
            //1, 1*1
            walls[cx][cy] = 1;
        } 
        else if (shape == 1) { 
            // 2, 2* 2
            walls[cx][cy] = 1;   walls[cx+1][cy] = 1;
            walls[cx][cy+1] = 1; walls[cx+1][cy+1] = 1;
        } 
        else if (shape == 2) { 
            // 3, 3*1
            walls[cx][cy] = 1; walls[cx+1][cy] = 1; walls[cx+2][cy] = 1;
        } 
        else if (shape == 3) { 
            // 4, 1*3
            walls[cx][cy] = 1; walls[cx][cy+1] = 1; walls[cx][cy+2] = 1;
        } 
        else if (shape == 4) { 
            // 5, L
            walls[cx][cy] = 1; 
            walls[cx][cy+1] = 1; 
            walls[cx+1][cy+1] = 1;
        }
    }
    // to make sure the edge areas are passable
    for(int i = 0; i < GRID_W; i++ ){
        walls[i][2] = 0;           // 顶边
        walls[i][GRID_H - 3] = 0;  // 底边
    }
    for(int i = 0; i < GRID_H; i++ ){
        walls[2][i] = 0;           // 左边
        walls[GRID_W - 3][i] = 0;  // 右边
    }

    //duplicate the left areas to the right
    for(int x = 1; x <= 7; x++) {
        for (int y = 1; y <= 10; y++) {
            // 中心对称公式
            walls[15 - x][11 - y] = walls[x][y]; 
        }
    }
    apply_doors_to_walls();
}

void draw_walls(){
    for(int i = 0; i < GRID_W; i ++){
        for(int j = 0; j < GRID_H; j ++){
            int cur_x = 20 * i;
            int cur_y = 20 * j;
            if(i == 0 || i == GRID_W - 1 || j == 0 || j == GRID_H - 1){
                Draw_Transparent_Image(cur_x, cur_y, wall_texture[5], 20, 20);
            }
            else if(walls[i][j] == 1){
                Draw_Transparent_Image(cur_x, cur_y, wall_texture[current_inner_texture], 20, 20);
            }
            if(walls[i][j] == 2){
                vga_draw_rect(cur_x, cur_y, 20, 20, Black);
            }
        }
    }
}

int can_move_to(int new_x, int new_y, int player_width, int player_height) {

    int x_offset = 2;
    int y_offset = 1;// since the animation does not excactly = 32*32, need the hitbox is smaller

    int hit_x = new_x + x_offset;
    int hit_y = new_y - y_offset;
    int hit_width = player_width - 2 * x_offset;
    int hit_height = player_height + y_offset;

    int left   = hit_x;
    int right  = hit_x + hit_width - 1;
    int top    = hit_y;
    int bottom = hit_y + hit_height - 1;

    int start_col = left / 20;
    int end_col   = right / 20;
    int start_row = top / 20;
    int end_row   = bottom / 20;

    if (start_col < 0 || end_col >= 16 || start_row < 0 || end_row >= 12) {
        return 0; //edge detection
    }
    for (int i = start_col; i <= end_col; i++) {
        for (int j = start_row; j <= end_row; j++) {
            if (walls[i][j] == 1) {
                return 0; // return 0 if the next move hit the wall
            }
        }
    }

    return 1; // move when no collision
}
